// Single + multilevel + hierarchical in one file. Keep chains shallow.
class Vehicle {
    void start() { System.out.println("vehicle starts"); }
}
class Car extends Vehicle { // single inheritance
    void honk() { System.out.println("car honks"); }
}
class ElectricCar extends Car { // multilevel: ElectricCar -> Car -> Vehicle
    @Override void start() { System.out.println("silent start"); }
}
class Animal {
    void sound() { System.out.println("generic sound"); }
}
class Dog extends Animal { // hierarchical: Dog and Cat share Animal
    @Override void sound() { System.out.println("bark"); }
}
class Cat extends Animal {
    @Override void sound() { System.out.println("meow"); }
}

interface Flyable {
    default void move() { System.out.println("fly"); }
}
interface Swimmable {
    default void move() { System.out.println("swim"); }
}
// Java forbids class Duck extends Bird, Fish. Interfaces recover the shape
// without duplicating ancestor state. The trade-off: YOU resolve collisions.
class Duck implements Flyable, Swimmable {
    @Override public void move() {
        // Must disambiguate. No implicit winner is the safe rule.
        Flyable.super.move();
        Swimmable.super.move();
    }
}

// WRONG SHAPE: Stack is-not-a ArrayList, it uses one.
// class Stack extends ArrayList<String> { } // inherits insertAt(0), clear, all sins.
import java.util.*;
// RIGHT SHAPE: expose only the stack contract, delegate to the list.
class Stack {
    private final Deque<String> store = new ArrayDeque<>(); // composition
    void push(String s) { store.push(s); }
    String pop() { return store.pop(); }
    String peek() { return store.peek(); }
    boolean isEmpty() { return store.isEmpty(); }
    // No insertAt, no set(index), no way to violate LIFO. The trade-off:
    // slightly more forwarding code now, zero taxonomy risk forever.
}
